use vstd::prelude::*;

verus! {

spec fn flipped<T>(s: Seq<T>) -> Seq<T>
    decreases s.len(),
{
    Seq::new(s.len(), |i: int| s[s.len() - 1 - i])
}

fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result@ == flipped(m@),
        result@.len() == m@.len(),
{
    let n = m.len();
    let mut result = Vec::with_capacity(n);

    for i in 0..n
        invariant
            n == m.len(),
            0 <= i <= n,
            result@.len() == i,
            result@ == Seq::new(i as nat, |k: int| m@[n as int - 1 - k]),
        decreases n - i,
    {
        // Index safety for m[n - 1 - i]
        assert(i < n);
        assert(n > 0);
        assert(0 <= (n - 1 - i) as int);
        assert((n - 1 - i) as int < n as int);

        result.push(m[n - 1 - i]);

        // Re-establish the invariant after the push
        assert(result@ == Seq::new((i + 1) as nat, |k: int| m@[n as int - 1 - k]));
    }

    // Connect loop post-state to the spec function
    assert(result@ == flipped(m@));
    result
}

} // verus!

